import { createStationTemperatureScorer } from '../../supabase/functions/_shared/station-temperature-scoring.ts';
import { unpackStationTemperatureWindow } from '../../supabase/functions/_shared/station-temperature-window.ts';
const count = Number(process.argv[2]);
const endAt = Date.parse('2026-09-10T00:00:00Z');
const stations = Array.from({length:184}, (_,i)=>({station_code:`S${i}`,latitude:41.5+i/184,longitude:2,altitude_m:500+i}));
const packed = Array.from({length:count},(_,day)=>JSON.stringify({
 version:'xema-arome-blend-v3',endAt:endAt-day*86400000,stations,encoding:'station-hour-series-v1',
 series:stations.map(s=>({stationCode:s.station_code,temperaturesC:Array.from({length:481},(_,h)=>15+Math.sin(h/12)*7),validation:'V'.repeat(481)}))
}));
global.gc!();
const before=process.memoryUsage();
const started=performance.now();
const windows = new Map(packed.map((json,i)=>[String(i),unpackStationTemperatureWindow(JSON.parse(json))!]));
const scorer=createStationTemperatureScorer(new Map(),windows);
const built=process.memoryUsage();
global.gc!();
const retained=process.memoryUsage();
// Keep the scorer and unpacked windows live across the memory readings.
if(scorer({sentinel:1},42,2).sentinel !== 1 || windows.size !== count) throw new Error('invalid benchmark');
console.log(JSON.stringify({kind:'synthetic Node 24 station-window allocation, not production peak',windows:count,stationsPerWindow:184,hourObjects:count*184*481,elapsedMs:performance.now()-started,heapBefore:before.heapUsed,heapAfterBuild:built.heapUsed,heapRetained:retained.heapUsed,heapIncrease:retained.heapUsed-before.heapUsed,rss:retained.rss}));
